import {
  Navbar,
  Nav,
  NavDropdown,
  Container,
  Form,
  InputGroup,
} from 'react-bootstrap';

import DateTime from './DateTime';
import { MoonStars, Search, Sun } from 'react-bootstrap-icons';
import { useContext, useState } from 'react';
import { AppContext } from '../App';
import OffCanvas from './Offcanvas';

function AppNavbar() {
  const { darkMode, setDarkMode } = useContext(AppContext);
  const { devices } = useContext(AppContext);
  const { setSearchTerm } = useContext(AppContext);
  const [searchQuery, setSearchQuery] = useState('');

  const toggleDarkMode = () => {
    setDarkMode(prevDarkMode => !prevDarkMode);
  };

  const filteredDevices = devices.filter(device => {
    const { name, ip, mac, vendor } = device;
    const searchLower = searchQuery.toLowerCase();
    return (
      name.toLowerCase().includes(searchLower) ||
      ip.toLowerCase().includes(searchLower) ||
      mac.toLowerCase().includes(searchLower) ||
      vendor.toLowerCase().includes(searchLower)
    );
  });

  const handleSearch = event => {
    event.preventDefault();
    setSearchTerm(filteredDevices);
  };

  return (
    <Navbar collapseOnSelect expand="lg" className="bg-body-tertiary">
      <Container>
        <Navbar.Brand>
          <img
            alt=""
            src="/logo.png"
            width="30"
            height="30"
            className="d-inline-block align-top"
          />{' '}
          LanGuard
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="responsive-navbar-nav" />
        <Navbar.Collapse
          id="responsive-navbar-nav"
          className="justify-content-between"
        >
          <Nav>
            <Form inline onSubmit={handleSearch}>
              <InputGroup>
                <InputGroup.Text id="search">
                  <Search />
                </InputGroup.Text>
                <Form.Control
                  placeholder="Search for devices"
                  aria-label="Search"
                  aria-describedby="search"
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                />
              </InputGroup>
            </Form>
          </Nav>
          <Nav>
            <DateTime />
          </Nav>
        </Navbar.Collapse>
        <Navbar.Collapse className="justify-content-end">
          <Nav>
            <NavDropdown
              title={
                <span
                  style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '32px',
                    height: '32px',
                    backgroundColor: 'black',
                    color: 'white',
                    fontSize: '20px',
                    fontWeight: 'bold',
                    borderRadius: '50%',
                  }}
                >
                  AD
                  {/* {`${userData.first_name.slice(0, 1)}${userData.last_name.slice(
                  0,
                  1
                )}`} */}
                </span>
              }
              id="collapsible-nav-dropdown"
            >
              <NavDropdown.ItemText>👤 User name</NavDropdown.ItemText>
              <NavDropdown.Divider />
              <NavDropdown.Item href="#action/3.1">
                ✏️ User preferences
              </NavDropdown.Item>
              <NavDropdown.Item href="#action/3.2">
                🔚 Sign out
              </NavDropdown.Item>
            </NavDropdown>
          </Nav>
          <Nav>
            <Nav.Link
              variant={darkMode ? 'dark' : 'light'}
              onClick={toggleDarkMode}
            >
              {darkMode ? (
                <>
                  <Sun size={20} />
                </>
              ) : (
                <>
                  <MoonStars size={20} />
                </>
              )}
            </Nav.Link>
            <OffCanvas />
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

export default AppNavbar;
